"""Verified local text-layer and OCR extraction for permit documents."""

import math
import re
import warnings
from collections.abc import Callable, Mapping
from contextlib import ExitStack
from dataclasses import dataclass
from io import BytesIO
from time import monotonic
from types import MappingProxyType
from typing import Final, TypeGuard

import pypdfium2
from PIL import Image, ImageOps, UnidentifiedImageError
from pypdf import PdfReader
from pypdf.errors import PdfReadError

from . import bounded_read
from .isolated_ocr import IsolatedOcrWorker
from .models import (
    DiscoveredDocument,
    DocumentExtractionError,
    ExtractedPage,
    ExtractionFailureKind,
    ExtractionMethod,
    PermitDocumentMime,
)
from .ocr import OcrEngine, TesseractOcr

_MEANINGFUL_TOKEN = re.compile(r"[0-9A-Za-z媛-??{2,}")
_MIN_MEANINGFUL_CHARACTERS: Final = 8
_MIN_MEANINGFUL_TOKENS: Final = 2
_LONG_TEXT_CHARACTERS: Final = 12
_MAX_RENDER_SCALE: Final = 8.0
_MIN_DOCUMENT_SECONDS: Final = 1.0
_MAX_DOCUMENT_SECONDS: Final = 3_600.0


def _valid_positive_real(value: object, ceiling: float) -> bool:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return False
    numeric_value = float(value)
    return math.isfinite(numeric_value) and 0 < numeric_value <= ceiling


@dataclass(frozen=True, slots=True)
class ExtractionLimits:
    """Resource ceilings for one untrusted local document."""

    max_source_bytes: int = 64 * 1024 * 1024
    max_image_dimension: int = 12_000
    max_image_pixels: int = 40_000_000
    max_pdf_pages: int = 200
    render_scale: float = 2.0
    max_rendered_dimension: int = 16_000
    max_rendered_pixels: int = 40_000_000
    max_total_rendered_pixels: int = 200_000_000
    max_document_seconds: float = 300.0

    def __post_init__(self) -> None:  # noqa: D105
        integer_limits = (
            self.max_source_bytes,
            self.max_image_dimension,
            self.max_image_pixels,
            self.max_pdf_pages,
            self.max_rendered_dimension,
            self.max_rendered_pixels,
            self.max_total_rendered_pixels,
        )
        if any(type(value) is not int or value <= 0 for value in integer_limits):
            raise DocumentExtractionError(
                ExtractionFailureKind.RESOURCE_LIMIT,
                "integer extraction limits must be positive integers",
            )
        if not _valid_positive_real(self.render_scale, _MAX_RENDER_SCALE):
            raise DocumentExtractionError(
                ExtractionFailureKind.RESOURCE_LIMIT,
                "render scale is outside the supported range",
            )
        if not _valid_positive_real(
            self.max_document_seconds,
            _MAX_DOCUMENT_SECONDS,
        ) or self.max_document_seconds < _MIN_DOCUMENT_SECONDS:
            raise DocumentExtractionError(
                ExtractionFailureKind.RESOURCE_LIMIT,
                "document OCR budget is outside the supported range",
            )


DEFAULT_EXTRACTION_LIMITS: Final = ExtractionLimits()


def _is_exact_tesseract(ocr: object) -> TypeGuard[TesseractOcr]:
    return type(ocr) is TesseractOcr


def _check_image_size(size: tuple[int, int], limits: ExtractionLimits) -> None:
    width, height = size
    if max(width, height) > limits.max_image_dimension or width * height > limits.max_image_pixels:
        raise DocumentExtractionError(
            ExtractionFailureKind.RESOURCE_LIMIT,
            "image dimensions exceed the extraction limit",
        )


def _ocr_page(
    image: Image.Image,
    page_number: int,
    ocr: OcrEngine,
    deadline: float,
) -> ExtractedPage:
    remaining = deadline - monotonic()
    if remaining <= 0:
        raise DocumentExtractionError(
            ExtractionFailureKind.OCR_TIMEOUT,
            "document OCR budget was exhausted",
        )
    result = ocr.extract(image, timeout_seconds=remaining)
    if monotonic() > deadline:
        raise DocumentExtractionError(
            ExtractionFailureKind.OCR_TIMEOUT,
            "document OCR budget was exhausted",
        )
    return ExtractedPage(
        page_number=page_number,
        text=result.text.strip(),
        method=ExtractionMethod.OCR,
        engine_version=result.engine_version,
    )


def _extract_image(
    contents: bytes,
    ocr: OcrEngine,
    limits: ExtractionLimits,
    deadline: float,
) -> tuple[ExtractedPage, ...]:
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("error", Image.DecompressionBombWarning)
            with ExitStack() as stack:
                source = stack.enter_context(Image.open(BytesIO(contents)))
                _check_image_size(source.size, limits)
                normalized = stack.enter_context(ImageOps.exif_transpose(source))
                _check_image_size(normalized.size, limits)
                image = stack.enter_context(normalized.convert("RGB"))
                return (_ocr_page(image, 1, ocr, deadline),)
    except (Image.DecompressionBombError, Image.DecompressionBombWarning) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.RESOURCE_LIMIT,
            "image decompression limit exceeded",
        ) from error
    except (OSError, UnidentifiedImageError) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.CORRUPT_DOCUMENT,
            "image cannot be decoded",
        ) from error


def _text_pages(contents: bytes, max_pdf_pages: int) -> tuple[str, ...]:
    try:
        reader = PdfReader(BytesIO(contents), strict=True)
    except (PdfReadError, EOFError, UnicodeError) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.CORRUPT_DOCUMENT,
            "PDF structure or text layer cannot be decoded",
        ) from error
    if reader.is_encrypted:
        raise DocumentExtractionError(
            ExtractionFailureKind.ENCRYPTED_PDF,
            "encrypted PDF requires manual review; no password was attempted",
        )
    if len(reader.pages) > max_pdf_pages:
        raise DocumentExtractionError(
            ExtractionFailureKind.RESOURCE_LIMIT,
            "PDF page count exceeds the extraction limit",
        )
    try:
        return tuple((page.extract_text() or "").strip() for page in reader.pages)
    except (PdfReadError, EOFError, UnicodeError) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.CORRUPT_DOCUMENT,
            "PDF structure or text layer cannot be decoded",
        ) from error


def _usable_text(text: str) -> bool:
    normalized = " ".join(text.split())
    tokens = _MEANINGFUL_TOKEN.findall(normalized)
    meaningful_characters = sum(character.isalnum() for character in normalized)
    return meaningful_characters >= _MIN_MEANINGFUL_CHARACTERS and (
        len(tokens) >= _MIN_MEANINGFUL_TOKENS
        or meaningful_characters >= _LONG_TEXT_CHARACTERS
    )


def _extract_pdf(
    contents: bytes,
    ocr: OcrEngine,
    limits: ExtractionLimits,
    deadline: float,
) -> tuple[ExtractedPage, ...]:
    text_pages = _text_pages(contents, limits.max_pdf_pages)
    if all(_usable_text(text) for text in text_pages):
        return tuple(
            ExtractedPage(number, text, ExtractionMethod.TEXT_LAYER, None)
            for number, text in enumerate(text_pages, start=1)
        )
    try:
        rendered_document = pypdfium2.PdfDocument(contents)
        pages: list[ExtractedPage] = []
        total_rendered_pixels = 0
        try:
            for page_number, text in enumerate(text_pages, start=1):
                if _usable_text(text):
                    pages.append(
                        ExtractedPage(page_number, text, ExtractionMethod.TEXT_LAYER, None)
                    )
                    continue
                rendered_page = rendered_document[page_number - 1]
                try:
                    page_width, page_height = rendered_page.get_size()
                    rendered_width = math.ceil(page_width * limits.render_scale)
                    rendered_height = math.ceil(page_height * limits.render_scale)
                    rendered_pixels = rendered_width * rendered_height
                    total_rendered_pixels += rendered_pixels
                    if (
                        max(rendered_width, rendered_height) > limits.max_rendered_dimension
                        or rendered_pixels > limits.max_rendered_pixels
                        or total_rendered_pixels > limits.max_total_rendered_pixels
                    ):
                        raise DocumentExtractionError(
                            ExtractionFailureKind.RESOURCE_LIMIT,
                            "rendered PDF dimensions exceed the extraction limit",
                        )
                    bitmap = rendered_page.render(scale=limits.render_scale)
                    try:
                        if bitmap.width * bitmap.height > limits.max_rendered_pixels:
                            raise DocumentExtractionError(
                                ExtractionFailureKind.RESOURCE_LIMIT,
                                "rendered PDF bitmap exceeds the extraction limit",
                            )
                        image = bitmap.to_pil()
                        pages.append(_ocr_page(image, page_number, ocr, deadline))
                    finally:
                        bitmap.close()
                finally:
                    rendered_page.close()
        finally:
            rendered_document.close()
    except (pypdfium2.PdfiumError, IndexError, OSError) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.CORRUPT_DOCUMENT,
            "PDF page cannot be rendered locally",
        ) from error
    return tuple(pages)


_EXTRACTORS: Final[
    Mapping[
        PermitDocumentMime,
        Callable[[bytes, OcrEngine, ExtractionLimits, float], tuple[ExtractedPage, ...]],
    ]
] = MappingProxyType(
    {
        PermitDocumentMime.PDF: _extract_pdf,
        PermitDocumentMime.JPEG: _extract_image,
        PermitDocumentMime.PNG: _extract_image,
    }
)


def extract_pages(
    document: DiscoveredDocument,
    ocr: OcrEngine,
    limits: ExtractionLimits = DEFAULT_EXTRACTION_LIMITS,
) -> tuple[ExtractedPage, ...]:
    """Extract 1-based page drafts without modifying or deleting the source."""
    deadline = monotonic() + limits.max_document_seconds
    contents = bounded_read.read_verified_contents(document, limits.max_source_bytes)
    extractor = _EXTRACTORS[document.mime_type]
    if _is_exact_tesseract(ocr):
        return extractor(contents, ocr, limits, deadline)
    with IsolatedOcrWorker(ocr) as isolated_ocr:
        return extractor(contents, isolated_ocr, limits, deadline)

"""Scan an inbox into reviewable permit-document successes and failures."""

import os
from collections.abc import Iterator
from dataclasses import dataclass
from pathlib import Path

from . import safe_io
from .models import (
    DiscoveredDocument,
    DiscoveryFailure,
    DiscoveryFailureKind,
    DocumentDiscoveryBatch,
    PermitDocumentDiscoveryError,
)


def _failure(kind: DiscoveryFailureKind, relative_path: Path | None, detail: str) -> DiscoveryFailure:
    """Build one explicit rejected-source record."""
    return DiscoveryFailure(kind, relative_path, detail)


def _relative(root: Path, path: Path) -> Path:
    """Return a normalized relative path for stable ordering and diagnostics."""
    return path.relative_to(root)


@dataclass(frozen=True, slots=True)
class _DirectoryToScan:
    """A verified directory that the scanner may visit without following a link."""

    path: Path


def _scan_directory(
    boundary: safe_io.RootBoundary, directory: Path
) -> Iterator[_DirectoryToScan | tuple[Path, Path] | DiscoveryFailure]:
    """Classify one directory's children without trusting link or reparse entries."""
    relative_directory = _relative(boundary.path, directory)
    directory_snapshot = safe_io.safe_path_snapshot(directory, boundary, relative_directory)
    match directory_snapshot:
        case DiscoveryFailure() as failure:
            yield failure
            return
        case safe_io.FileSnapshot() as snapshot:
            if not snapshot.is_directory:
                yield _failure(DiscoveryFailureKind.INBOX_UNREADABLE, relative_directory, "not a directory")
                return
    try:
        with os.scandir(directory) as entries:
            ordered_entries = tuple(sorted(entries, key=lambda entry: entry.name.casefold()))
    except OSError as error:
        yield _failure(DiscoveryFailureKind.INBOX_UNREADABLE, relative_directory, str(error))
        return
    for entry in ordered_entries:
        candidate = Path(entry.path)
        relative_path = _relative(boundary.path, candidate)
        try:
            snapshot = safe_io.path_snapshot(candidate)
        except OSError as error:
            yield _failure(DiscoveryFailureKind.FILE_UNREADABLE, relative_path, str(error))
            continue
        if snapshot.is_reparse:
            yield _failure(DiscoveryFailureKind.REPARSE_POINT, relative_path, "link or reparse point")
        elif snapshot.is_directory:
            yield _DirectoryToScan(candidate)
        elif snapshot.is_regular:
            yield candidate, relative_path


def _scan(boundary: safe_io.RootBoundary) -> Iterator[tuple[Path, Path] | DiscoveryFailure]:
    """Traverse every verified directory and yield candidates or independent failures."""
    pending = [boundary.path]
    while pending:
        directory = pending.pop()
        for result in _scan_directory(boundary, directory):
            match result:
                case DiscoveryFailure() as failure:
                    yield failure
                case _DirectoryToScan(path=path):
                    pending.append(path)
                case (path, relative_path):
                    yield path, relative_path


def _reparse_ancestor_failure(root: Path) -> DiscoveryFailure | None:
    """Report the first inbox ancestor that is a link or Windows reparse point."""
    for ancestor in safe_io.path_ancestors(root.parent, None):
        if safe_io.path_snapshot(ancestor).is_reparse:
            return _failure(DiscoveryFailureKind.REPARSE_POINT, None, "inbox ancestor is a link or reparse point")
    return None


def _inbox_initial_snapshot(inbox: Path, root: Path) -> safe_io.FileSnapshot | DiscoveryFailure:
    try:
        return safe_io.path_snapshot(root)
    except FileNotFoundError:
        return _failure(DiscoveryFailureKind.INBOX_MISSING, None, f"{inbox} does not exist")
    except OSError as error:
        return _failure(DiscoveryFailureKind.INBOX_UNREADABLE, None, str(error))


def _invalid_inbox_root(inbox: Path, initial: safe_io.FileSnapshot) -> DiscoveryFailure | None:
    if initial.is_reparse:
        return _failure(DiscoveryFailureKind.REPARSE_POINT, None, "inbox is a link or reparse point")
    if not initial.is_directory:
        return _failure(DiscoveryFailureKind.INBOX_NOT_DIRECTORY, None, f"{inbox} is not a directory")
    return None


def _inbox_root(inbox: Path) -> safe_io.RootBoundary | DiscoveryFailure:
    """Accept only an existing inbox with no link or reparse ancestor."""
    root = inbox.absolute()
    initial_result = _inbox_initial_snapshot(inbox, root)
    match initial_result:
        case DiscoveryFailure() as failure:
            return failure
        case safe_io.FileSnapshot() as initial:
            pass
    invalid_root = _invalid_inbox_root(inbox, initial)
    if invalid_root is not None:
        return invalid_root
    try:
        ancestor_failure = _reparse_ancestor_failure(root)
        if ancestor_failure is not None:
            return ancestor_failure
        resolved = root.resolve(strict=True)
    except (OSError, RuntimeError) as error:
        return _failure(DiscoveryFailureKind.INBOX_UNREADABLE, None, str(error))
    if not safe_io.same_lexical_path(root, resolved):
        return _failure(DiscoveryFailureKind.REPARSE_POINT, None, "inbox resolved through a different path")
    boundary = safe_io.RootBoundary(root, initial)
    root_failure = safe_io.verify_root(boundary, None)
    return root_failure if root_failure is not None else boundary


def discover_document_batch(inbox: Path) -> DocumentDiscoveryBatch:
    """Return every valid document and independent failure from one inbox traversal."""
    root_result = _inbox_root(inbox)
    match root_result:
        case DiscoveryFailure() as failure:
            return DocumentDiscoveryBatch((), (failure,))
        case safe_io.RootBoundary() as boundary:
            documents: list[DiscoveredDocument] = []
            failures: list[DiscoveryFailure] = []
            for discovered in _scan(boundary):
                match discovered:
                    case DiscoveryFailure() as failure:
                        failures.append(failure)
                    case (path, relative_path):
                        result = safe_io.read_document(path, boundary, relative_path)
                        match result:
                            case DiscoveryFailure() as failure:
                                failures.append(failure)
                            case DiscoveredDocument() as document:
                                documents.append(document)
            root_failure = safe_io.verify_root(boundary, None)
            if root_failure is not None:
                return DocumentDiscoveryBatch((), (*failures, root_failure))
            return DocumentDiscoveryBatch(tuple(sorted(documents, key=lambda document: document.relative_path.as_posix())), tuple(failures))


def discover_documents(inbox: Path) -> tuple[DiscoveredDocument, ...]:
    """Return usable documents while retaining root failures as typed exceptions."""
    batch = discover_document_batch(inbox)
    root_failures = tuple(failure for failure in batch.failures if failure.relative_path is None)
    if root_failures:
        raise PermitDocumentDiscoveryError(root_failures)
    return batch.documents

"""Descriptor-bound file reads for permit-document discovery."""

import hashlib
import os
import stat
from collections.abc import Iterator
from dataclasses import dataclass
from pathlib import Path
from typing import Final

from . import win32_safe_open
from .models import (
    DiscoveredDocument,
    DiscoveryFailure,
    DiscoveryFailureKind,
    PermitDocumentMime,
    SourceProvenance,
)

READ_CHUNK_SIZE: Final = 1024 * 1024
_SIGNATURE_SIZE: Final = 16
_PDF_SIGNATURE: Final = b"%PDF-"
_PNG_SIGNATURE: Final = b"\x89PNG\r\n\x1a\n"
_JPEG_SIGNATURE: Final = b"\xff\xd8\xff"
_OPEN_FLAGS: Final = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
_EXTENSION_MIME: Final[dict[str, PermitDocumentMime]] = {
    ".pdf": PermitDocumentMime.PDF,
    ".jpg": PermitDocumentMime.JPEG,
    ".jpeg": PermitDocumentMime.JPEG,
    ".png": PermitDocumentMime.PNG,
}


@dataclass(frozen=True, slots=True)
class FileSnapshot:
    """A filesystem identity observed through a path or already-open handle."""

    device: int
    inode: int
    byte_size: int
    modified_ns: int
    is_directory: bool
    is_regular: bool
    is_reparse: bool


@dataclass(frozen=True, slots=True)
class RootBoundary:
    """A lexical inbox directory bound to the identity observed before traversal."""

    path: Path
    snapshot: FileSnapshot


@dataclass(frozen=True, slots=True)
class ReadPayload:
    """Bytes and descriptor identities produced by one verified file read."""

    signature: bytes
    sha256: str
    byte_size: int
    opened_snapshot: FileSnapshot
    after_read_snapshot: FileSnapshot


def _failure(kind: DiscoveryFailureKind, relative_path: Path | None, detail: str) -> DiscoveryFailure:
    """Build a typed rejection for one file-system boundary failure."""
    return DiscoveryFailure(kind, relative_path, detail)


def _snapshot_from_stat(status: os.stat_result, is_reparse: bool) -> FileSnapshot:
    """Convert a platform stat response into a comparable immutable identity."""
    return FileSnapshot(
        status.st_dev,
        status.st_ino,
        status.st_size,
        status.st_mtime_ns,
        stat.S_ISDIR(status.st_mode),
        stat.S_ISREG(status.st_mode),
        is_reparse,
    )


def path_snapshot(path: Path) -> FileSnapshot:
    """Inspect a path entry without following a link or Windows reparse point."""
    status = path.lstat()
    attributes = getattr(status, "st_file_attributes", 0)
    return _snapshot_from_stat(
        status,
        stat.S_ISLNK(status.st_mode) or bool(attributes & stat.FILE_ATTRIBUTE_REPARSE_POINT),
    )


def handle_snapshot(file_descriptor: int) -> FileSnapshot:
    """Capture the opened descriptor identity trusted for content reads."""
    return _snapshot_from_stat(os.fstat(file_descriptor), is_reparse=False)


def open_read_descriptor(path: Path) -> int:
    """Use a Win32 no-follow open on Windows and O_NOFOLLOW where POSIX provides it."""
    return win32_safe_open.open_read_descriptor(path) if os.name == "nt" else os.open(path, _OPEN_FLAGS)


def same_identity(left: FileSnapshot, right: FileSnapshot) -> bool:
    """Compare durable identity fields rather than timestamps."""
    return (left.device, left.inode) == (right.device, right.inode)


def same_lexical_path(left: Path, right: Path) -> bool:
    """Compare platform-normalized paths without resolving a second link chain."""
    return os.path.normcase(os.path.normpath(str(left))) == os.path.normcase(os.path.normpath(str(right)))


def path_ancestors(path: Path, boundary: Path | None) -> Iterator[Path]:
    """Yield a path and its parents, stopping after the inclusive boundary."""
    current = path
    while True:
        yield current
        if current in (boundary, current.parent):
            return
        current = current.parent


def verify_root(boundary: RootBoundary, relative_path: Path | None) -> DiscoveryFailure | None:
    """Reject an inbox that becomes a link, non-directory, or different directory identity."""
    try:
        for ancestor in path_ancestors(boundary.path.parent, None):
            if path_snapshot(ancestor).is_reparse:
                return _failure(DiscoveryFailureKind.REPARSE_POINT, relative_path, "inbox ancestor is a link or reparse point")
        current = path_snapshot(boundary.path)
    except OSError as error:
        return _failure(DiscoveryFailureKind.INBOX_UNREADABLE, relative_path, str(error))
    if current.is_reparse:
        return _failure(DiscoveryFailureKind.REPARSE_POINT, relative_path, "inbox became a link or reparse point")
    if not current.is_directory or not same_identity(boundary.snapshot, current):
        return _failure(DiscoveryFailureKind.IDENTITY_MISMATCH, relative_path, "inbox identity changed")
    return None


def safe_path_snapshot(
    path: Path, boundary: RootBoundary, relative_path: Path | None
) -> FileSnapshot | DiscoveryFailure:
    """Reject reparse ancestors and prove a lexical path still resolves under root."""
    try:
        target: FileSnapshot | None = None
        root_failure = verify_root(boundary, relative_path)
        if root_failure is not None:
            return root_failure
        for ancestor in path_ancestors(path, boundary.path):
            snapshot = path_snapshot(ancestor)
            if snapshot.is_reparse:
                return _failure(DiscoveryFailureKind.REPARSE_POINT, relative_path, "link or reparse point")
            if ancestor == path:
                target = snapshot
        resolved = path.resolve(strict=True)
        _ = resolved.relative_to(boundary.path)
    except (FileNotFoundError, OSError, RuntimeError, ValueError) as error:
        return _failure(DiscoveryFailureKind.SYMLINK_ESCAPE, relative_path, str(error))
    if target is None:
        return _failure(DiscoveryFailureKind.FILE_UNREADABLE, relative_path, "missing path snapshot")
    root_failure = verify_root(boundary, relative_path)
    return root_failure if root_failure is not None else target


def _mime_from_signature(signature: bytes) -> PermitDocumentMime | None:
    """Identify only supported document types from their binary signatures."""
    if signature.startswith(_PDF_SIGNATURE):
        return PermitDocumentMime.PDF
    if signature.startswith(_PNG_SIGNATURE):
        return PermitDocumentMime.PNG
    if signature.startswith(_JPEG_SIGNATURE):
        return PermitDocumentMime.JPEG
    return None


def checked_file_snapshot(path: Path, boundary: RootBoundary, relative_path: Path) -> FileSnapshot | DiscoveryFailure:
    """Require a contained regular file before or after opening it."""
    result = safe_path_snapshot(path, boundary, relative_path)
    match result:
        case DiscoveryFailure() as failure:
            return failure
        case FileSnapshot(is_regular=False):
            return _failure(DiscoveryFailureKind.FILE_UNREADABLE, relative_path, "not a regular file")
        case FileSnapshot() as snapshot:
            return snapshot


def _site_code(relative_path: Path) -> str | None:
    """Use the first directory below inbox as the optional site-code hint."""
    return relative_path.parts[0] if len(relative_path.parts) > 1 else None


def _read_open_descriptor(
    path: Path, boundary: RootBoundary, relative_path: Path, before_snapshot: FileSnapshot
) -> ReadPayload | DiscoveryFailure:
    """Read through one descriptor after revalidating the still-named path identity."""
    try:
        file_descriptor = open_read_descriptor(path)
        with os.fdopen(file_descriptor, "rb") as source:
            opened_snapshot = handle_snapshot(source.fileno())
            after_open = checked_file_snapshot(path, boundary, relative_path)
            match after_open:
                case DiscoveryFailure() as failure:
                    return failure
                case FileSnapshot() as path_snapshot:
                    if not same_identity(before_snapshot, opened_snapshot) or not same_identity(
                        opened_snapshot, path_snapshot
                    ):
                        return _failure(DiscoveryFailureKind.IDENTITY_MISMATCH, relative_path, "path changed")
            signature = source.read(_SIGNATURE_SIZE)
            digest = hashlib.sha256(signature)
            byte_size = len(signature)
            while chunk := source.read(READ_CHUNK_SIZE):
                digest.update(chunk)
                byte_size += len(chunk)
            after_read = handle_snapshot(source.fileno())
    except OSError as error:
        return _failure(DiscoveryFailureKind.FILE_UNREADABLE, relative_path, str(error))
    return ReadPayload(signature, digest.hexdigest(), byte_size, opened_snapshot, after_read)


def _changed_during_read(before: FileSnapshot, payload: ReadPayload, final: FileSnapshot) -> bool:
    """Detect descriptor or pathname replacement before trusting extracted file metadata."""
    return (
        not same_identity(before, payload.after_read_snapshot)
        or not same_identity(payload.after_read_snapshot, final)
        or payload.after_read_snapshot.byte_size != payload.byte_size
        or payload.after_read_snapshot.modified_ns != payload.opened_snapshot.modified_ns
    )


def _document_from_payload(
    path: Path,
    relative_path: Path,
    payload: ReadPayload,
    boundary: RootBoundary,
) -> DiscoveredDocument | DiscoveryFailure:
    """Accept only a file whose extension and content signature describe the same format."""
    declared_mime = _EXTENSION_MIME.get(path.suffix.casefold())
    if declared_mime is None:
        return _failure(DiscoveryFailureKind.UNSUPPORTED_EXTENSION, relative_path, f"unsupported extension {path.suffix or '<none>'}")
    detected_mime = _mime_from_signature(payload.signature)
    if detected_mime is None:
        return _failure(DiscoveryFailureKind.UNSUPPORTED_MIME, relative_path, "unsupported file signature")
    if declared_mime is not detected_mime:
        return _failure(DiscoveryFailureKind.EXTENSION_MISMATCH, relative_path, "extension and signature differ")
    provenance = SourceProvenance(
        inbox_root=boundary.path,
        root_device=boundary.snapshot.device,
        root_inode=boundary.snapshot.inode,
        file_device=payload.after_read_snapshot.device,
        file_inode=payload.after_read_snapshot.inode,
        file_modified_ns=payload.after_read_snapshot.modified_ns,
    )
    return DiscoveredDocument(
        path,
        relative_path,
        _site_code(relative_path),
        detected_mime,
        payload.byte_size,
        payload.sha256,
        provenance,
    )


def read_document(path: Path, boundary: RootBoundary, relative_path: Path) -> DiscoveredDocument | DiscoveryFailure:
    """Hash one verified descriptor and reject path or handle replacement."""
    before = checked_file_snapshot(path, boundary, relative_path)
    match before:
        case DiscoveryFailure() as failure:
            return failure
        case FileSnapshot() as before_snapshot:
            payload = _read_open_descriptor(path, boundary, relative_path, before_snapshot)
    match payload:
        case DiscoveryFailure() as failure:
            return failure
        case ReadPayload() as read_payload:
            after_read_path = checked_file_snapshot(path, boundary, relative_path)
    match after_read_path:
        case DiscoveryFailure() as failure:
            return failure
        case FileSnapshot() as final_snapshot:
            if _changed_during_read(before_snapshot, read_payload, final_snapshot):
                return _failure(DiscoveryFailureKind.IDENTITY_MISMATCH, relative_path, "file changed while reading")
    return _document_from_payload(path, relative_path, read_payload, boundary)

"""Bounded descriptor reads for previously discovered permit documents."""

import hashlib
import os

from . import safe_io
from .models import (
    DiscoveredDocument,
    DiscoveryFailure,
    DiscoveryFailureKind,
    DocumentExtractionError,
    ExtractionFailureKind,
)


def _source_error(failure: DiscoveryFailure) -> DocumentExtractionError:
    if failure.kind in (DiscoveryFailureKind.REPARSE_POINT, DiscoveryFailureKind.SYMLINK_ESCAPE):
        return DocumentExtractionError(
            ExtractionFailureKind.SOURCE_REPARSE,
            "source path became a link or reparse point",
        )
    return DocumentExtractionError(
        ExtractionFailureKind.SOURCE_CHANGED,
        "source identity changed after discovery",
    )


def _verified_boundary(document: DiscoveredDocument) -> safe_io.RootBoundary:
    provenance = document.provenance
    try:
        root_snapshot = safe_io.path_snapshot(provenance.inbox_root)
    except OSError as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.SOURCE_ROOT_CHANGED,
            "source inbox is no longer available",
        ) from error
    if root_snapshot.is_reparse:
        raise DocumentExtractionError(
            ExtractionFailureKind.SOURCE_REPARSE,
            "source inbox became a link or reparse point",
        )
    if (root_snapshot.device, root_snapshot.inode) != (
        provenance.root_device,
        provenance.root_inode,
    ):
        raise DocumentExtractionError(
            ExtractionFailureKind.SOURCE_ROOT_CHANGED,
            "source inbox identity changed",
        )
    return safe_io.RootBoundary(provenance.inbox_root, root_snapshot)


def _verified_source_snapshot(
    document: DiscoveredDocument, boundary: safe_io.RootBoundary
) -> safe_io.FileSnapshot:
    result = safe_io.checked_file_snapshot(
        document.absolute_path,
        boundary,
        document.relative_path,
    )
    if isinstance(result, DiscoveryFailure):
        raise _source_error(result)
    provenance = document.provenance
    if (result.device, result.inode, result.modified_ns) != (
        provenance.file_device,
        provenance.file_inode,
        provenance.file_modified_ns,
    ):
        raise DocumentExtractionError(
            ExtractionFailureKind.SOURCE_CHANGED,
            "source identity changed after discovery",
        )
    return result


def _read_bounded_descriptor(
    document: DiscoveredDocument,
    before: safe_io.FileSnapshot,
    max_bytes: int,
) -> tuple[bytes, safe_io.FileSnapshot, str]:
    try:
        descriptor = safe_io.open_read_descriptor(document.absolute_path)
        with os.fdopen(descriptor, "rb") as source:
            opened = safe_io.handle_snapshot(source.fileno())
            if not safe_io.same_identity(before, opened):
                raise DocumentExtractionError(
                    ExtractionFailureKind.SOURCE_CHANGED,
                    "source changed while opening",
                )
            if opened.byte_size > max_bytes:
                raise DocumentExtractionError(
                    ExtractionFailureKind.RESOURCE_LIMIT,
                    "source exceeds the byte limit",
                )
            chunks: list[bytes] = []
            digest = hashlib.sha256()
            byte_size = 0
            while chunk := source.read(
                min(safe_io.READ_CHUNK_SIZE, max_bytes + 1 - byte_size)
            ):
                chunks.append(chunk)
                digest.update(chunk)
                byte_size += len(chunk)
                if byte_size > max_bytes:
                    raise DocumentExtractionError(
                        ExtractionFailureKind.RESOURCE_LIMIT,
                        "source exceeds the byte limit",
                    )
            after_read = safe_io.handle_snapshot(source.fileno())
    except OSError as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.SOURCE_CHANGED,
            "source cannot be read safely",
        ) from error
    return b"".join(chunks), after_read, digest.hexdigest()


def read_verified_contents(document: DiscoveredDocument, max_bytes: int) -> bytes:
    """Return hash-verified bytes from one no-follow descriptor within the bound."""
    boundary = _verified_boundary(document)
    before = _verified_source_snapshot(document, boundary)
    contents, after_read, sha256 = _read_bounded_descriptor(document, before, max_bytes)
    final = _verified_source_snapshot(document, boundary)
    if not safe_io.same_identity(before, after_read) or not safe_io.same_identity(after_read, final):
        raise DocumentExtractionError(
            ExtractionFailureKind.SOURCE_CHANGED,
            "source changed while reading",
        )
    if len(contents) != document.byte_size or sha256 != document.sha256:
        raise DocumentExtractionError(
            ExtractionFailureKind.SOURCE_CHANGED,
            "source content changed after discovery",
        )
    return contents

"""Killable process boundary for non-Tesseract OCR adapters."""

import math
import multiprocessing
import pickle
import time
from contextlib import suppress
from typing import TYPE_CHECKING, Final, Protocol, Self, TypeGuard, cast, final

if TYPE_CHECKING:
    from multiprocessing.process import BaseProcess

from PIL import Image

from .models import (
    DocumentExtractionError,
    ExtractionFailureKind,
    OcrResult,
)
from .ocr import OcrEngine

_STOP_GRACE_SECONDS: Final = 0.05
_FAILED_DETAIL: Final = "isolated OCR adapter failed"
_MESSAGE_ITEMS: Final = 2


class _Connection(Protocol):
    def send(self, obj: object) -> None: ...

    def recv(self) -> object: ...

    def poll(self, timeout: float = 0.0) -> bool: ...

    def close(self) -> None: ...


def _is_request(value: object) -> TypeGuard[tuple[Image.Image, int | float]]:
    if not isinstance(value, tuple):
        return False
    items = cast("tuple[object, ...]", value)
    return (
        len(items) == _MESSAGE_ITEMS
        and isinstance(items[0], Image.Image)
        and not isinstance(items[1], bool)
        and isinstance(items[1], (int, float))
    )


def _is_response(
    value: object,
) -> TypeGuard[tuple[bool, OcrResult | ExtractionFailureKind]]:
    if not isinstance(value, tuple):
        return False
    items = cast("tuple[object, ...]", value)
    return (
        len(items) == _MESSAGE_ITEMS
        and isinstance(items[0], bool)
        and isinstance(items[1], (OcrResult, ExtractionFailureKind))
    )


def _result_response(result: object) -> tuple[bool, OcrResult | ExtractionFailureKind]:
    if isinstance(result, OcrResult):
        return True, result
    return False, ExtractionFailureKind.OCR_FAILED


def _worker_main(engine: OcrEngine, connection: _Connection) -> None:
    try:
        while True:
            try:
                request = connection.recv()
            except (EOFError, OSError):
                return
            if request is None:
                return
            if not _is_request(request):
                connection.send((False, ExtractionFailureKind.OCR_FAILED))
                continue
            image = request[0]
            timeout_seconds = float(request[1])
            try:
                result = cast(
                    "object",
                    engine.extract(image, timeout_seconds=timeout_seconds),
                )
                connection.send(_result_response(result))
            except DocumentExtractionError as error:
                connection.send((False, error.kind))
            except Exception:  # noqa: BLE001
                connection.send((False, ExtractionFailureKind.OCR_FAILED))
    except (BrokenPipeError, EOFError, OSError):
        return
    finally:
        connection.close()


@final
class IsolatedOcrWorker:
    """Run one generic OCR engine in one killable process per document."""

    def __init__(self, engine: OcrEngine) -> None:  # noqa: D107
        self._engine = engine
        self._connection: _Connection | None = None
        self._process: BaseProcess | None = None

    def __enter__(self) -> Self:  # noqa: D105
        return self

    def __exit__(self, *_exc_info: object) -> None:  # noqa: D105
        self.close()

    def _start(self) -> None:
        if self._process is not None:
            return
        try:
            _ = pickle.dumps(self._engine)
        except Exception as error:
            raise DocumentExtractionError(
                ExtractionFailureKind.OCR_FAILED,
                "OCR adapter cannot start in the isolated worker",
            ) from error
        context = multiprocessing.get_context("spawn")
        parent_connection, child_connection = context.Pipe()
        process = context.Process(
            target=_worker_main,
            args=(self._engine, child_connection),
            daemon=True,
            name="era-permit-ocr",
        )
        try:
            process.start()
        except BaseException as error:
            if process.pid is not None:
                if process.is_alive():
                    process.terminate()
                process.join()
            parent_connection.close()
            child_connection.close()
            with suppress(ValueError):
                process.close()
            raise DocumentExtractionError(
                ExtractionFailureKind.OCR_FAILED,
                "OCR adapter cannot start in the isolated worker",
            ) from error
        child_connection.close()
        self._connection = parent_connection
        self._process = process

    def _stop(self, force: bool) -> None:
        process = self._process
        connection = self._connection
        self._process = None
        self._connection = None
        if connection is not None:
            if not force:
                with suppress(BrokenPipeError, EOFError, OSError):
                    connection.send(None)
            connection.close()
        if process is None:
            return
        if force and process.is_alive():
            process.terminate()
        process.join(_STOP_GRACE_SECONDS)
        if process.is_alive():
            process.kill()
            process.join()
        process.close()

    def close(self) -> None:
        """Stop the document worker and release every process and IPC handle."""
        self._stop(force=False)

    def extract(
        self,
        image: Image.Image,
        timeout_seconds: float | None = None,
    ) -> OcrResult:
        """Enforce the supplied deadline even when the adapter ignores it."""
        if (
            timeout_seconds is None
            or not math.isfinite(timeout_seconds)
            or timeout_seconds <= 0
        ):
            raise DocumentExtractionError(
                ExtractionFailureKind.OCR_TIMEOUT,
                "document OCR budget was exhausted",
            )
        deadline = time.monotonic() + timeout_seconds
        self._start()
        connection = self._connection
        process = self._process
        if connection is None or process is None:
            raise DocumentExtractionError(
                ExtractionFailureKind.OCR_FAILED,
                _FAILED_DETAIL,
            )
        try:
            connection.send((image, timeout_seconds))
        except (BrokenPipeError, EOFError, OSError, TypeError) as error:
            self._stop(force=True)
            raise DocumentExtractionError(
                ExtractionFailureKind.OCR_FAILED,
                _FAILED_DETAIL,
            ) from error
        remaining = deadline - time.monotonic()
        if remaining <= 0 or not connection.poll(remaining):
            self._stop(force=True)
            raise DocumentExtractionError(
                ExtractionFailureKind.OCR_TIMEOUT,
                "document OCR budget was exhausted",
            )
        try:
            response = connection.recv()
        except (BrokenPipeError, EOFError, OSError, TypeError) as error:
            self._stop(force=True)
            raise DocumentExtractionError(
                ExtractionFailureKind.OCR_FAILED,
                _FAILED_DETAIL,
            ) from error
        if not _is_response(response):
            self._stop(force=True)
            raise DocumentExtractionError(
                ExtractionFailureKind.OCR_FAILED,
                _FAILED_DETAIL,
            )
        succeeded, payload = response
        if succeeded and isinstance(payload, OcrResult):
            return payload
        self._stop(force=True)
        kind = payload if isinstance(payload, ExtractionFailureKind) else ExtractionFailureKind.OCR_FAILED
        raise DocumentExtractionError(kind, _FAILED_DETAIL)

from __future__ import annotations

import hashlib
import os
import socket
from concurrent.futures import ThreadPoolExecutor
from datetime import date
from typing import ClassVar, Final

import httpx2
import pytest
from pydantic import BaseModel, ConfigDict, TypeAdapter

from scripts.importer.models import PermitUpdate, SiteCode
from scripts.importer.transaction import (
    ImportClient,
    ImportClientError,
    ImportEnvelope,
    SupabaseConfig,
)
from scripts.seed_builder.models import PermitStatus, PermitType

if os.environ.get("ERA_RUN_LOCAL_INTEGRATION") != "1":
    pytest.skip("local Supabase integration is opt-in", allow_module_level=True)

_LIMITS: Final = httpx2.Limits(
    max_connections=200,
    max_keepalive_connections=40,
    keepalive_expiry=30.0,
)
_TIMEOUT: Final = httpx2.Timeout(connect=5.0, read=30.0, write=10.0, pool=10.0)
_SOCKET_OPTIONS: Final = [(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)]


class _AuthSession(BaseModel):
    model_config: ClassVar[ConfigDict] = ConfigDict(frozen=True)

    access_token: str


class _BatchRow(BaseModel):
    model_config: ClassVar[ConfigDict] = ConfigDict(frozen=True)

    id: str


class _PermitRow(BaseModel):
    model_config: ClassVar[ConfigDict] = ConfigDict(frozen=True)

    detail: str | None


def _client(headers: dict[str, str]) -> httpx2.Client:
    transport = httpx2.HTTPTransport(
        http2=True,
        retries=3,
        limits=_LIMITS,
        socket_options=_SOCKET_OPTIONS,
    )
    return httpx2.Client(
        transport=transport,
        timeout=_TIMEOUT,
        follow_redirects=False,
        headers=headers,
    )


def _required_environment(name: str) -> str:
    value = os.environ.get(name, "").strip()
    if not value:
        pytest.fail(f"missing integration setting: {name}")
    return value


def _login(email: str) -> SupabaseConfig:
    url = _required_environment("SUPABASE_URL").rstrip("/")
    anon_key = _required_environment("SUPABASE_ANON_KEY")
    password = _required_environment("LOCAL_SUPABASE_TEST_PASSWORD")
    with _client({"apikey": anon_key, "Content-Type": "application/json"}) as client:
        response = client.post(
            f"{url}/auth/v1/token?grant_type=password",
            json={"email": email, "password": password},
        )
        _ = response.raise_for_status()
        session = _AuthSession.model_validate_json(response.content)
    return SupabaseConfig(
        url=url,
        project_key=anon_key,
        access_token=session.access_token,
    )


def _update(site_code: str, permit_type: PermitType, detail: str) -> PermitUpdate:
    return PermitUpdate(
        site_code=SiteCode(site_code),
        permit_type=permit_type,
        applicable=True,
        grade=None,
        detail=detail,
        items=(),
        quantity=None,
        permit_no=None,
        authority=None,
        issued_on=date(2026, 2, 3),
        conditions=None,
        status=PermitStatus.ACTIVE,
    )


def _envelope(label: str, rows: tuple[PermitUpdate, ...]) -> ImportEnvelope:
    return ImportEnvelope(
        source_name=f"{label}.csv",
        source_sha256=hashlib.sha256(label.encode()).hexdigest(),
        rows=rows,
    )


@pytest.mark.parametrize(
