        confirmed_by = null,
        confirmed_at = null,
        closed_by = null,
        closed_at = null,
        return_reason = p_reason
    where id = p_id;
  else
    raise exception '지원하지 않는 조치 대상 상태입니다. (%)', p_to;
  end if;
end $$;

