"""Scan an inbox into reviewable permit-document successes and failures."""

import os
from collections.abc import Iterator
from dataclasses import dataclass
from pathlib import Path

from . import safe_io
from .models import (
    DiscoveredDocument,
    DiscoveryFailure,
    DiscoveryFailureKind,
    DocumentDiscoveryBatch,
    PermitDocumentDiscoveryError,
)


def _failure(kind: DiscoveryFailureKind, relative_path: Path | None, detail: str) -> DiscoveryFailure:
    """Build one explicit rejected-source record."""
    return DiscoveryFailure(kind, relative_path, detail)


def _relative(root: Path, path: Path) -> Path:
    """Return a normalized relative path for stable ordering and diagnostics."""
    return path.relative_to(root)


@dataclass(frozen=True, slots=True)
class _DirectoryToScan:
    """A verified directory that the scanner may visit without following a link."""

    path: Path


def _scan_directory(
    boundary: safe_io.RootBoundary, directory: Path
) -> Iterator[_DirectoryToScan | tuple[Path, Path] | DiscoveryFailure]:
    """Classify one directory's children without trusting link or reparse entries."""
    relative_directory = _relative(boundary.path, directory)
    directory_snapshot = safe_io.safe_path_snapshot(directory, boundary, relative_directory)
    match directory_snapshot:
        case DiscoveryFailure() as failure:
            yield failure
            return
        case safe_io.FileSnapshot() as snapshot:
            if not snapshot.is_directory:
                yield _failure(DiscoveryFailureKind.INBOX_UNREADABLE, relative_directory, "not a directory")
                return
    try:
        with os.scandir(directory) as entries:
            ordered_entries = tuple(sorted(entries, key=lambda entry: entry.name.casefold()))
    except OSError as error:
        yield _failure(DiscoveryFailureKind.INBOX_UNREADABLE, relative_directory, str(error))
        return
    for entry in ordered_entries:
        candidate = Path(entry.path)
        relative_path = _relative(boundary.path, candidate)
        try:
            snapshot = safe_io.path_snapshot(candidate)
        except OSError as error:
            yield _failure(DiscoveryFailureKind.FILE_UNREADABLE, relative_path, str(error))
            continue
        if snapshot.is_reparse:
            yield _failure(DiscoveryFailureKind.REPARSE_POINT, relative_path, "link or reparse point")
        elif snapshot.is_directory:
            yield _DirectoryToScan(candidate)
        elif snapshot.is_regular:
            yield candidate, relative_path


def _scan(boundary: safe_io.RootBoundary) -> Iterator[tuple[Path, Path] | DiscoveryFailure]:
    """Traverse every verified directory and yield candidates or independent failures."""
    pending = [boundary.path]
    while pending:
        directory = pending.pop()
        for result in _scan_directory(boundary, directory):
            match result:
                case DiscoveryFailure() as failure:
                    yield failure
                case _DirectoryToScan(path=path):
                    pending.append(path)
                case (path, relative_path):
                    yield path, relative_path


def _reparse_ancestor_failure(root: Path) -> DiscoveryFailure | None:
    """Report the first inbox ancestor that is a link or Windows reparse point."""
    for ancestor in safe_io.path_ancestors(root.parent, None):
        if safe_io.path_snapshot(ancestor).is_reparse:
            return _failure(DiscoveryFailureKind.REPARSE_POINT, None, "inbox ancestor is a link or reparse point")
    return None


def _inbox_initial_snapshot(inbox: Path, root: Path) -> safe_io.FileSnapshot | DiscoveryFailure:
    try:
        return safe_io.path_snapshot(root)
    except FileNotFoundError:
        return _failure(DiscoveryFailureKind.INBOX_MISSING, None, f"{inbox} does not exist")
    except OSError as error:
        return _failure(DiscoveryFailureKind.INBOX_UNREADABLE, None, str(error))


def _invalid_inbox_root(inbox: Path, initial: safe_io.FileSnapshot) -> DiscoveryFailure | None:
    if initial.is_reparse:
        return _failure(DiscoveryFailureKind.REPARSE_POINT, None, "inbox is a link or reparse point")
    if not initial.is_directory:
        return _failure(DiscoveryFailureKind.INBOX_NOT_DIRECTORY, None, f"{inbox} is not a directory")
    return None


def _inbox_root(inbox: Path) -> safe_io.RootBoundary | DiscoveryFailure:
    """Accept only an existing inbox with no link or reparse ancestor."""
    root = inbox.absolute()
    initial_result = _inbox_initial_snapshot(inbox, root)
    match initial_result:
        case DiscoveryFailure() as failure:
            return failure
        case safe_io.FileSnapshot() as initial:
            pass
    invalid_root = _invalid_inbox_root(inbox, initial)
    if invalid_root is not None:
        return invalid_root
    try:
        ancestor_failure = _reparse_ancestor_failure(root)
        if ancestor_failure is not None:
            return ancestor_failure
        resolved = root.resolve(strict=True)
    except (OSError, RuntimeError) as error:
        return _failure(DiscoveryFailureKind.INBOX_UNREADABLE, None, str(error))
    if not safe_io.same_lexical_path(root, resolved):
        return _failure(DiscoveryFailureKind.REPARSE_POINT, None, "inbox resolved through a different path")
    boundary = safe_io.RootBoundary(root, initial)
    root_failure = safe_io.verify_root(boundary, None)
    return root_failure if root_failure is not None else boundary


def discover_document_batch(inbox: Path) -> DocumentDiscoveryBatch:
    """Return every valid document and independent failure from one inbox traversal."""
    root_result = _inbox_root(inbox)
    match root_result:
        case DiscoveryFailure() as failure:
            return DocumentDiscoveryBatch((), (failure,))
        case safe_io.RootBoundary() as boundary:
            documents: list[DiscoveredDocument] = []
            failures: list[DiscoveryFailure] = []
            for discovered in _scan(boundary):
                match discovered:
                    case DiscoveryFailure() as failure:
                        failures.append(failure)
                    case (path, relative_path):
                        result = safe_io.read_document(path, boundary, relative_path)
                        match result:
                            case DiscoveryFailure() as failure:
                                failures.append(failure)
                            case DiscoveredDocument() as document:
                                documents.append(document)
            root_failure = safe_io.verify_root(boundary, None)
            if root_failure is not None:
                return DocumentDiscoveryBatch((), (*failures, root_failure))
            return DocumentDiscoveryBatch(tuple(sorted(documents, key=lambda document: document.relative_path.as_posix())), tuple(failures))


def discover_documents(inbox: Path) -> tuple[DiscoveredDocument, ...]:
    """Return usable documents while retaining root failures as typed exceptions."""
    batch = discover_document_batch(inbox)
    root_failures = tuple(failure for failure in batch.failures if failure.relative_path is None)
    if root_failures:
        raise PermitDocumentDiscoveryError(root_failures)
    return batch.documents

"""Descriptor-bound file reads for permit-document discovery."""

import hashlib
import os
import stat
from collections.abc import Iterator
from dataclasses import dataclass
from pathlib import Path
from typing import Final

from . import win32_safe_open
from .models import (
    DiscoveredDocument,
    DiscoveryFailure,
    DiscoveryFailureKind,
    PermitDocumentMime,
    SourceProvenance,
)

READ_CHUNK_SIZE: Final = 1024 * 1024
_SIGNATURE_SIZE: Final = 16
_PDF_SIGNATURE: Final = b"%PDF-"
_PNG_SIGNATURE: Final = b"\x89PNG\r\n\x1a\n"
_JPEG_SIGNATURE: Final = b"\xff\xd8\xff"
_OPEN_FLAGS: Final = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
_EXTENSION_MIME: Final[dict[str, PermitDocumentMime]] = {
    ".pdf": PermitDocumentMime.PDF,
    ".jpg": PermitDocumentMime.JPEG,
    ".jpeg": PermitDocumentMime.JPEG,
    ".png": PermitDocumentMime.PNG,
}


@dataclass(frozen=True, slots=True)
class FileSnapshot:
    """A filesystem identity observed through a path or already-open handle."""

    device: int
    inode: int
    byte_size: int
    modified_ns: int
    is_directory: bool
    is_regular: bool
    is_reparse: bool


@dataclass(frozen=True, slots=True)
class RootBoundary:
    """A lexical inbox directory bound to the identity observed before traversal."""

    path: Path
    snapshot: FileSnapshot


@dataclass(frozen=True, slots=True)
class ReadPayload:
    """Bytes and descriptor identities produced by one verified file read."""

    signature: bytes
    sha256: str
    byte_size: int
    opened_snapshot: FileSnapshot
    after_read_snapshot: FileSnapshot


def _failure(kind: DiscoveryFailureKind, relative_path: Path | None, detail: str) -> DiscoveryFailure:
    """Build a typed rejection for one file-system boundary failure."""
    return DiscoveryFailure(kind, relative_path, detail)


def _snapshot_from_stat(status: os.stat_result, is_reparse: bool) -> FileSnapshot:
    """Convert a platform stat response into a comparable immutable identity."""
    return FileSnapshot(
        status.st_dev,
        status.st_ino,
        status.st_size,
        status.st_mtime_ns,
        stat.S_ISDIR(status.st_mode),
        stat.S_ISREG(status.st_mode),
        is_reparse,
    )


def path_snapshot(path: Path) -> FileSnapshot:
    """Inspect a path entry without following a link or Windows reparse point."""
    status = path.lstat()
    attributes = getattr(status, "st_file_attributes", 0)
    return _snapshot_from_stat(
        status,
        stat.S_ISLNK(status.st_mode) or bool(attributes & stat.FILE_ATTRIBUTE_REPARSE_POINT),
    )


def handle_snapshot(file_descriptor: int) -> FileSnapshot:
    """Capture the opened descriptor identity trusted for content reads."""
    return _snapshot_from_stat(os.fstat(file_descriptor), is_reparse=False)


def open_read_descriptor(path: Path) -> int:
    """Use a Win32 no-follow open on Windows and O_NOFOLLOW where POSIX provides it."""
    return win32_safe_open.open_read_descriptor(path) if os.name == "nt" else os.open(path, _OPEN_FLAGS)


def same_identity(left: FileSnapshot, right: FileSnapshot) -> bool:
    """Compare durable identity fields rather than timestamps."""
    return (left.device, left.inode) == (right.device, right.inode)


def same_lexical_path(left: Path, right: Path) -> bool:
    """Compare platform-normalized paths without resolving a second link chain."""
    return os.path.normcase(os.path.normpath(str(left))) == os.path.normcase(os.path.normpath(str(right)))


def path_ancestors(path: Path, boundary: Path | None) -> Iterator[Path]:
    """Yield a path and its parents, stopping after the inclusive boundary."""
    current = path
    while True:
        yield current
        if current in (boundary, current.parent):
            return
        current = current.parent


def verify_root(boundary: RootBoundary, relative_path: Path | None) -> DiscoveryFailure | None:
    """Reject an inbox that becomes a link, non-directory, or different directory identity."""
    try:
        for ancestor in path_ancestors(boundary.path.parent, None):
            if path_snapshot(ancestor).is_reparse:
                return _failure(DiscoveryFailureKind.REPARSE_POINT, relative_path, "inbox ancestor is a link or reparse point")
        current = path_snapshot(boundary.path)
    except OSError as error:
        return _failure(DiscoveryFailureKind.INBOX_UNREADABLE, relative_path, str(error))
    if current.is_reparse:
        return _failure(DiscoveryFailureKind.REPARSE_POINT, relative_path, "inbox became a link or reparse point")
    if not current.is_directory or not same_identity(boundary.snapshot, current):
        return _failure(DiscoveryFailureKind.IDENTITY_MISMATCH, relative_path, "inbox identity changed")
    return None


def safe_path_snapshot(
    path: Path, boundary: RootBoundary, relative_path: Path | None
) -> FileSnapshot | DiscoveryFailure:
    """Reject reparse ancestors and prove a lexical path still resolves under root."""
    try:
        target: FileSnapshot | None = None
        root_failure = verify_root(boundary, relative_path)
        if root_failure is not None:
            return root_failure
        for ancestor in path_ancestors(path, boundary.path):
            snapshot = path_snapshot(ancestor)
            if snapshot.is_reparse:
                return _failure(DiscoveryFailureKind.REPARSE_POINT, relative_path, "link or reparse point")
            if ancestor == path:
                target = snapshot
        resolved = path.resolve(strict=True)
        _ = resolved.relative_to(boundary.path)
    except (FileNotFoundError, OSError, RuntimeError, ValueError) as error:
        return _failure(DiscoveryFailureKind.SYMLINK_ESCAPE, relative_path, str(error))
    if target is None:
        return _failure(DiscoveryFailureKind.FILE_UNREADABLE, relative_path, "missing path snapshot")
    root_failure = verify_root(boundary, relative_path)
    return root_failure if root_failure is not None else target


def _mime_from_signature(signature: bytes) -> PermitDocumentMime | None:
    """Identify only supported document types from their binary signatures."""
    if signature.startswith(_PDF_SIGNATURE):
        return PermitDocumentMime.PDF
    if signature.startswith(_PNG_SIGNATURE):
        return PermitDocumentMime.PNG
    if signature.startswith(_JPEG_SIGNATURE):
        return PermitDocumentMime.JPEG
    return None


def checked_file_snapshot(path: Path, boundary: RootBoundary, relative_path: Path) -> FileSnapshot | DiscoveryFailure:
    """Require a contained regular file before or after opening it."""
    result = safe_path_snapshot(path, boundary, relative_path)
    match result:
        case DiscoveryFailure() as failure:
            return failure
        case FileSnapshot(is_regular=False):
            return _failure(DiscoveryFailureKind.FILE_UNREADABLE, relative_path, "not a regular file")
        case FileSnapshot() as snapshot:
            return snapshot


def _site_code(relative_path: Path) -> str | None:
    """Use the first directory below inbox as the optional site-code hint."""
    return relative_path.parts[0] if len(relative_path.parts) > 1 else None


def _read_open_descriptor(
    path: Path, boundary: RootBoundary, relative_path: Path, before_snapshot: FileSnapshot
) -> ReadPayload | DiscoveryFailure:
    """Read through one descriptor after revalidating the still-named path identity."""
    try:
        file_descriptor = open_read_descriptor(path)
        with os.fdopen(file_descriptor, "rb") as source:
            opened_snapshot = handle_snapshot(source.fileno())
            after_open = checked_file_snapshot(path, boundary, relative_path)
            match after_open:
                case DiscoveryFailure() as failure:
                    return failure
                case FileSnapshot() as path_snapshot:
                    if not same_identity(before_snapshot, opened_snapshot) or not same_identity(
                        opened_snapshot, path_snapshot
                    ):
                        return _failure(DiscoveryFailureKind.IDENTITY_MISMATCH, relative_path, "path changed")
            signature = source.read(_SIGNATURE_SIZE)
            digest = hashlib.sha256(signature)
            byte_size = len(signature)
            while chunk := source.read(READ_CHUNK_SIZE):
                digest.update(chunk)
                byte_size += len(chunk)
            after_read = handle_snapshot(source.fileno())
    except OSError as error:
        return _failure(DiscoveryFailureKind.FILE_UNREADABLE, relative_path, str(error))
    return ReadPayload(signature, digest.hexdigest(), byte_size, opened_snapshot, after_read)


def _changed_during_read(before: FileSnapshot, payload: ReadPayload, final: FileSnapshot) -> bool:
    """Detect descriptor or pathname replacement before trusting extracted file metadata."""
    return (
        not same_identity(before, payload.after_read_snapshot)
        or not same_identity(payload.after_read_snapshot, final)
        or payload.after_read_snapshot.byte_size != payload.byte_size
        or payload.after_read_snapshot.modified_ns != payload.opened_snapshot.modified_ns
    )


def _document_from_payload(
    path: Path,
    relative_path: Path,
    payload: ReadPayload,
    boundary: RootBoundary,
) -> DiscoveredDocument | DiscoveryFailure:
    """Accept only a file whose extension and content signature describe the same format."""
    declared_mime = _EXTENSION_MIME.get(path.suffix.casefold())
    if declared_mime is None:
        return _failure(DiscoveryFailureKind.UNSUPPORTED_EXTENSION, relative_path, f"unsupported extension {path.suffix or '<none>'}")
    detected_mime = _mime_from_signature(payload.signature)
    if detected_mime is None:
        return _failure(DiscoveryFailureKind.UNSUPPORTED_MIME, relative_path, "unsupported file signature")
    if declared_mime is not detected_mime:
        return _failure(DiscoveryFailureKind.EXTENSION_MISMATCH, relative_path, "extension and signature differ")
    provenance = SourceProvenance(
        inbox_root=boundary.path,
        root_device=boundary.snapshot.device,
        root_inode=boundary.snapshot.inode,
        file_device=payload.after_read_snapshot.device,
        file_inode=payload.after_read_snapshot.inode,
        file_modified_ns=payload.after_read_snapshot.modified_ns,
    )
    return DiscoveredDocument(
        path,
        relative_path,
        _site_code(relative_path),
        detected_mime,
        payload.byte_size,
        payload.sha256,
        provenance,
    )


def read_document(path: Path, boundary: RootBoundary, relative_path: Path) -> DiscoveredDocument | DiscoveryFailure:
    """Hash one verified descriptor and reject path or handle replacement."""
    before = checked_file_snapshot(path, boundary, relative_path)
    match before:
        case DiscoveryFailure() as failure:
            return failure
        case FileSnapshot() as before_snapshot:
            payload = _read_open_descriptor(path, boundary, relative_path, before_snapshot)
    match payload:
        case DiscoveryFailure() as failure:
            return failure
        case ReadPayload() as read_payload:
            after_read_path = checked_file_snapshot(path, boundary, relative_path)
    match after_read_path:
        case DiscoveryFailure() as failure:
            return failure
        case FileSnapshot() as final_snapshot:
            if _changed_during_read(before_snapshot, read_payload, final_snapshot):
                return _failure(DiscoveryFailureKind.IDENTITY_MISMATCH, relative_path, "file changed while reading")
    return _document_from_payload(path, relative_path, read_payload, boundary)

"""Typed Supabase RPC boundary for transactional permit imports."""

from __future__ import annotations

import hashlib
import socket
from dataclasses import dataclass
from typing import TYPE_CHECKING, ClassVar, Final, Self, override
from urllib.parse import urlsplit
from uuid import UUID

import httpx2
from pydantic import BaseModel, ConfigDict, TypeAdapter

from . import models
from .postgrest_errors import parse_safe_postgrest_error

if TYPE_CHECKING:
    from collections.abc import Mapping
    from pathlib import Path

_LIMITS: Final = httpx2.Limits(
    max_connections=200,
    max_keepalive_connections=40,
    keepalive_expiry=30.0,
)
_TIMEOUT: Final = httpx2.Timeout(connect=5.0, read=30.0, write=10.0, pool=10.0)
_SOCKET_OPTIONS: Final = [(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)]
_UUID_ADAPTER: Final = TypeAdapter(UUID)
_CONFIG_KEYS: Final = frozenset(("SUPABASE_URL", "SUPABASE_ANON_KEY", "SUPABASE_ACCESS_TOKEN"))
_MINIMUM_CREDENTIAL_LENGTH: Final = 16
_QUOTED_VALUE_MINIMUM_LENGTH: Final = 2
_ASCII_PRINTABLE_START: Final = 32
_ASCII_DELETE: Final = 127


class ImportEnvelope(BaseModel):
    """One validated file and its exact-byte idempotency identity."""

    model_config: ClassVar[ConfigDict] = ConfigDict(frozen=True)

    source_name: str
    source_sha256: str
    rows: tuple[models.PermitUpdate, ...]


@dataclass(frozen=True, slots=True)
class SupabaseConfig:
    """User-scoped credentials required by the import RPC."""

    url: str
    project_key: str
    access_token: str


@dataclass(frozen=True, slots=True)
class ImportClientError(RuntimeError):
    """A safe operator-facing RPC error that never contains credentials."""

    reason: str

    @override
    def __str__(self) -> str:
        """Return the credential-safe operator message."""
        return self.reason

    @classmethod
    def missing_config(cls) -> Self:
        """Build the error for absent user-scoped connection values."""
        return cls("SUPABASE_URL, SUPABASE_ANON_KEY, SUPABASE_ACCESS_TOKEN을 설정해야 합니다.")

    @classmethod
    def request_failed(cls) -> Self:
        """Build the redacted transport or response error."""
        return cls("Supabase 인허가 반영 요청에 실패했습니다.")

    @classmethod
    def rpc_rejected(cls, code: str, message: str) -> Self:
        """Build an allowlisted actionable server rejection."""
        return cls(f"Supabase 요청 거부 ({code}): {message}")

    @classmethod
    def config_file_failed(cls) -> Self:
        """Build the error for an unreadable local environment file."""
        return cls(".env 설정 파일을 읽을 수 없습니다.")

    @classmethod
    def invalid_config(cls) -> Self:
        """Build one redacted error for malformed URLs, credentials, or dotenv syntax."""
        return cls("Supabase 연결 설정 형식이 올바르지 않습니다.")


def build_envelope(snapshot: models.PermitImportSnapshot) -> ImportEnvelope:
    """Bind an already validated plan to the exact input bytes."""
    return ImportEnvelope(
        source_name=snapshot.source_name,
        source_sha256=hashlib.sha256(snapshot.source_bytes).hexdigest(),
        rows=snapshot.plan.updates,
    )


def _dotenv_values(dotenv_path: Path | None) -> Mapping[str, str]:
    if dotenv_path is None or not dotenv_path.is_file():
        return {}
    try:
        lines = dotenv_path.read_text(encoding="utf-8-sig").splitlines()
    except OSError as error:
        raise ImportClientError.config_file_failed() from error
    values: dict[str, str] = {}
    for raw_line in lines:
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        key, separator, raw_value = line.partition("=")
        key = key.strip()
        value = raw_value.strip()
        if not separator or key not in _CONFIG_KEYS or key in values or not value:
            raise ImportClientError.invalid_config()
        starts_quoted = value[0] in "'\""
        ends_quoted = value[-1] in "'\""
        if starts_quoted or ends_quoted:
            if (
                len(value) < _QUOTED_VALUE_MINIMUM_LENGTH
                or value[0] != value[-1]
                or value[0] not in "'\""
            ):
                raise ImportClientError.invalid_config()
            quote = value[0]
            value = value[1:-1]
            if not value or value[0:1].isspace() or value[-1:].isspace() or quote in value:
                raise ImportClientError.invalid_config()
        elif any(character.isspace() for character in value) or "#" in value:
            raise ImportClientError.invalid_config()
        values[key] = value
    return values


def _valid_url(value: str) -> bool:
    try:
        parsed = urlsplit(value)
        _ = parsed.port
    except ValueError:
        return False
    return (
        parsed.scheme in {"http", "https"}
        and parsed.hostname is not None
        and parsed.username is None
        and parsed.password is None
        and parsed.query == ""
        and parsed.fragment == ""
        and parsed.path in {"", "/"}
    )


def _valid_credential(value: str) -> bool:
    return len(value) >= _MINIMUM_CREDENTIAL_LENGTH and all(
        not character.isspace() and _ASCII_PRINTABLE_START < ord(character) < _ASCII_DELETE
        for character in value
    )


def load_config(environment: Mapping[str, str], dotenv_path: Path | None = None) -> SupabaseConfig:
    """Parse user-scoped Supabase connection settings from environment values."""
    file_values = _dotenv_values(dotenv_path)
    url = (environment.get("SUPABASE_URL") or file_values.get("SUPABASE_URL", "")).rstrip("/")
    project_key = environment.get("SUPABASE_ANON_KEY") or file_values.get("SUPABASE_ANON_KEY", "")
    access_token = environment.get("SUPABASE_ACCESS_TOKEN") or file_values.get(
        "SUPABASE_ACCESS_TOKEN", ""
    )
    if not url or not project_key or not access_token:
        raise ImportClientError.missing_config()
    if not _valid_url(url) or not _valid_credential(project_key) or not _valid_credential(access_token):
        raise ImportClientError.invalid_config()
    return SupabaseConfig(url=url, project_key=project_key, access_token=access_token)


class ImportClient:
    """Post one validated envelope through the authenticated PostgREST RPC."""

    _config: SupabaseConfig
    _transport: httpx2.BaseTransport | None

    def __init__(self, config: SupabaseConfig, transport: httpx2.BaseTransport | None = None) -> None:
        """Retain the immutable user-scoped configuration."""
        self._config = config
        self._transport = transport

    def apply_envelope(self, envelope: ImportEnvelope) -> UUID:
        """Apply the envelope once and return its durable audit batch identifier."""
        transport = self._transport or httpx2.HTTPTransport(
            http2=True, retries=0, limits=_LIMITS, socket_options=_SOCKET_OPTIONS
        )
        headers = {
            "Authorization": f"Bearer {self._config.access_token}",
            "apikey": self._config.project_key,
            "Content-Type": "application/json",
        }
        try:
            with httpx2.Client(
                transport=transport,
                timeout=_TIMEOUT,
                follow_redirects=False,
                headers=headers,
            ) as client:
                response = client.post(
                    f"{self._config.url}/rest/v1/rpc/admin_import_permit_updates",
                    json={"p_envelope": envelope.model_dump(mode="json")},
                )
                if response.is_error:
                    safe_error = parse_safe_postgrest_error(response.content)
                    if safe_error is not None:
                        raise ImportClientError.rpc_rejected(safe_error.code, safe_error.message)
                _ = response.raise_for_status()
                return _UUID_ADAPTER.validate_json(response.content)
        except ImportClientError:
            raise
        except (httpx2.HTTPError, ValueError, TypeError) as error:
            raise ImportClientError.request_failed() from error

from __future__ import annotations

from typing import TYPE_CHECKING, override

import pytest
