from __future__ import annotations

import os
import shutil
import subprocess
import time
from contextlib import contextmanager
from typing import TYPE_CHECKING
from uuid import uuid4

import pytest

if TYPE_CHECKING:
    from collections.abc import Iterator

if os.environ.get("ERA_RUN_LOCAL_INTEGRATION") != "1":
    pytest.skip("local Supabase concurrency is opt-in", allow_module_level=True)

DOCKER = shutil.which("docker") or "docker"
COMMAND = [DOCKER, "exec", "-i", "supabase_db_backend-mvp", "psql", "-U", "postgres", "-d", "postgres", "-XqAt", "-v", "ON_ERROR_STOP=1"]


def _sql(sql: str) -> str:
    result = subprocess.run(COMMAND, input=sql, text=True, capture_output=True, check=True, timeout=20)  # noqa: S603
    return result.stdout.strip()


@contextmanager
def _connection() -> Iterator[subprocess.Popen[str]]:
    process = subprocess.Popen(COMMAND, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)  # noqa: S603
    try:
        yield process
    finally:
        if process.poll() is None:
            process.kill()
        _ = process.communicate(timeout=10)


def _send(connection: subprocess.Popen[str], sql: str) -> None:
    assert connection.stdin is not None
    _ = connection.stdin.write(sql + "\n")
    connection.stdin.flush()


def _ready(connection: subprocess.Popen[str]) -> None:
    assert connection.stdout is not None
    assert connection.stdout.readline().strip() == "ready"


def _wait_for_blocked(application: str) -> bool:
    deadline = time.monotonic() + 3
    while time.monotonic() < deadline:
        if _sql(f"select count(*) from pg_stat_activity where application_name='{application}' and wait_event_type='Lock'") == "1":
            return True
        time.sleep(0.05)
    return False


@pytest.mark.parametrize("mutation", ["insert", "update", "delete"])
@pytest.mark.parametrize("edit_first", [True, False])
def test_parent_transition_serializes_item_mutations(mutation: str, edit_first: bool) -> None:
    actor, manager, head, assessment, item = (str(uuid4()) for _ in range(5))
    application = "era-race-" + assessment
    setup = f"""
insert into auth.users(id) values('{actor}'),('{manager}'),('{head}');
insert into profiles(id,name,email) values('{actor}','Race officer','{actor}@example.test'),('{manager}','Race manager','{manager}@example.test'),('{head}','Race head','{head}@example.test');
insert into role_assignments(user_id,role,scope,site_id) select '{actor}','env_officer','site',id from sites where code='RMC-01';
insert into role_assignments(user_id,role,scope,site_id) select '{manager}','plant_manager','site',id from sites where code='RMC-01';
insert into role_assignments(user_id,role,scope,division_code) values('{head}','dept_head','division','RMC');
insert into era_assessments(id,site_id,year,revision,author_id) select '{assessment}',id,2199,0,'{actor}' from sites where code='RMC-01';
"""
    insert = f"insert into era_items(id,assessment_id,site_id,seq,process,activity,aspect,impact,media,likelihood,severity,needs_improvement) select '{item}','{assessment}',id,1,'test','test','test','test','air',4,4,true from sites where code='RMC-01';"
    operation = {
        "insert": insert,
        "update": f"update era_items set likelihood=4,severity=4,needs_improvement=true where id='{item}';",
        "delete": f"delete from era_items where id='{item}';",
    }[mutation]
    _ = _sql(setup + (insert.replace(",4,4,true", ",1,1,false") if mutation != "insert" else ""))
    try:
        with _connection() as first, _connection() as second:
            edit = f"set local role authenticated; set local request.jwt.claim.sub='{actor}'; {operation}"
            submit = f"set local role authenticated; set local request.jwt.claim.sub='{manager}'; select transition_era('{assessment}','submitted');"
            _send(first, "begin; " + (edit if edit_first else submit) + "select 'ready';")
            if not edit_first:
                assert first.stdout is not None
                _ = first.stdout.readline()
            _ready(first)
            _send(second, f"set application_name='{application}'; begin; set local statement_timeout='8s'; " + (submit if edit_first else edit) + "commit;")
            assert _wait_for_blocked(application), "item edit and transition did not acquire conflicting parent locks"
            _send(first, "commit;")
            second_output, second_error = second.communicate(timeout=10)
            if edit_first:
                assert second.returncode == 0, second_error
            else:
                assert second.returncode != 0, second_output
                assert "ERA items require a draft or returned assessment" in second_error
        _ = _sql(f"begin; set local role authenticated; set local request.jwt.claim.sub='{manager}'; select transition_era('{assessment}','reviewed'); set local request.jwt.claim.sub='{head}'; select transition_era('{assessment}','approved'); commit;")
        assert _sql(f"select count(*) from actions where source_type='era' and source_id='{item}'") == ("1" if edit_first and mutation != "delete" else "0")
        assert _sql(f"select count(*) from era_items where assessment_id='{assessment}' and significant and needs_improvement") == ("1" if edit_first and mutation != "delete" else "0")
    finally:
        _ = _sql(f"delete from actions where source_id='{item}'; delete from era_assessments where id='{assessment}'; delete from role_assignments where user_id in ('{actor}','{manager}','{head}'); delete from profiles where id in ('{actor}','{manager}','{head}'); delete from auth.users where id in ('{actor}','{manager}','{head}'); delete from audit_log where row_id='{assessment}' or actor in ('{actor}','{manager}','{head}');")

