create or replace function assign_action(p_id uuid, p_owner uuid, p_owner_name text) returns void
language plpgsql security definer set search_path = public as $$
declare
  v actions;
  v_owner_name text;
begin
  select * into v from actions where id = p_id for update;

  if not found then
    raise exception 'Action % does not exist.', p_id using errcode = 'P0002';
  end if;

  if not has_site_role(v.site_id, array['plant_manager', 'dept_head']::app_role[]) then
    raise exception '공장장 또는 실무부서장만 조치를 배정할 수 있습니다.';
  end if;

  if v.status not in ('open', 'returned') then
    raise exception 'open 또는 returned 상태의 조치만 배정할 수 있습니다.';
  end if;

  select profile.name
  into v_owner_name
  from public.eligible_action_assignees(v.site_id) profile
  where profile.id = p_owner;

  if v_owner_name is null then
    raise exception '조치 담당자는 해당 사업장의 환경기술인 또는 공장장이어야 합니다.';
  end if;

  if p_owner_name is distinct from v_owner_name then
    raise exception '조치 담당자 이름이 사용자 프로필과 일치하지 않습니다.';
  end if;

  update actions
  set owner_id = p_owner,
      owner_name = v_owner_name,
      status = 'open',
      done_at = null,
      done_by = null,
      confirmed_by = null,
      confirmed_at = null,
      closed_by = null,
      closed_at = null,
      return_reason = null
  where id = p_id;
end $$;

create or replace function public.safe_audit_projection(p_table text, p_row jsonb)
returns jsonb language sql immutable set search_path = public, pg_temp as $$
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb)
  from jsonb_each(p_row)
  where key = any(case p_table
    when 'permit_documents' then array['id','source_sha256','site_id_candidate','permit_type_candidate','status','reviewer_id','reviewed_at','extraction_method','page_count','error_stage','created_at','updated_at']
    when 'site_permits' then array['id','site_id','permit_type','applicable','quantity','status','issued_on','created_at','updated_at']
    when 'obligation_tasks' then array['id','site_id','type_code','due_date','status','done_on','done_by','confirmed_by','confirmed_at','created_at']
    when 'era_assessments' then array['id','site_id','year','revision','template_id','status','author_id','submitted_at','reviewed_by','reviewed_at','approved_by','approved_at','created_at']
    when 'actions' then array['id','site_id','source_type','source_id','owner_id','due_date','status','done_at','done_by','confirmed_by','confirmed_at','closed_by','closed_at','created_by','created_at']
    when 'incidents' then array['id','site_id','occurred_on','media','sanction','fine_amount','report_rule','created_by','created_at']
    else array[]::text[] end)
$$;
revoke all on function public.safe_audit_projection(text,jsonb) from public, anon, authenticated;

create or replace function public.audit_trigger() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_data jsonb;
begin
  v_data := safe_audit_projection(tg_table_name,
    case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end);
  if tg_op = 'UPDATE' then
    v_data := v_data || jsonb_build_object('previous_status', to_jsonb(old)->'status');
  end if;
  insert into audit_log(table_name,row_id,op,actor,data)
  values(tg_table_name,coalesce(new.id,old.id),tg_op,auth.uid(),v_data);
  return coalesce(new,old);
end $$;

-- Historic snapshots retain only factual allowlisted values; no history is inferred.
update public.audit_log set data = public.safe_audit_projection(table_name,data);

drop policy a_read on public.audit_log;
create policy a_read on public.audit_log for select to authenticated using (
  has_role(array['she_staff','she_lead']::app_role[])
  and (
    table_name <> 'permit_documents'
    or (data->>'site_id_candidate' is null and has_role(array['she_staff']::app_role[]))
    or (data->>'site_id_candidate' is not null and can_read_site((data->>'site_id_candidate')::uuid))
  )
);

-- Non-failed stage values contradict the current state. Unknown historical
-- failed stages remain NULL rather than inventing a processing history.
update public.permit_documents set error_stage = null where status <> 'failed' and error_stage is not null;
alter table public.permit_documents add constraint permit_documents_failure_details
  check (status = 'failed' or (error_stage is null and error_code is null and error_message is null));

