import hashlib
import os
from pathlib import Path
from time import monotonic
from typing import TYPE_CHECKING

from . import safe_io
from .models import DiscoveryFailure, DiscoveryFailureKind, PermitDocumentMime

if TYPE_CHECKING:
    from typing import BinaryIO


def detect_mime(signature: bytes) -> PermitDocumentMime | None:
    """Identify supported formats from the first bounded signature read."""
    if signature.startswith(b"%PDF-"):
        return PermitDocumentMime.PDF
    if signature.startswith(b"\x89PNG\r\n\x1a\n"):
        return PermitDocumentMime.PNG
    if signature.startswith(b"\xff\xd8\xff"):
        return PermitDocumentMime.JPEG
    return None


def _hash_payload(source: BinaryIO, relative: Path, snapshot: safe_io.FileSnapshot, declared: PermitDocumentMime, deadline: float) -> safe_io.ReadPayload | DiscoveryFailure:
    signature = source.read(16)
    detected = detect_mime(signature)
    if detected is None:
        return DiscoveryFailure(DiscoveryFailureKind.UNSUPPORTED_MIME, relative, "unsupported file signature")
    if detected is not declared:
        return DiscoveryFailure(DiscoveryFailureKind.EXTENSION_MISMATCH, relative, "extension and signature differ")
    digest = hashlib.sha256(signature)
    byte_size = len(signature)
    while True:
        if monotonic() > deadline or byte_size > safe_io.MAX_DISCOVERY_BYTES:
            return DiscoveryFailure(DiscoveryFailureKind.RESOURCE_LIMIT, relative, "source exceeds discovery byte or time limit")
        chunk = source.read(min(safe_io.READ_CHUNK_SIZE, safe_io.MAX_DISCOVERY_BYTES + 1 - byte_size))
        if not chunk:
            break
        digest.update(chunk)
        byte_size += len(chunk)
    return safe_io.ReadPayload(signature, digest.hexdigest(), byte_size, snapshot, safe_io.handle_snapshot(source.fileno()))


def read_payload(path: Path, boundary: safe_io.RootBoundary, relative: Path, before: safe_io.FileSnapshot, declared: PermitDocumentMime) -> safe_io.ReadPayload | DiscoveryFailure:
    """Check descriptor identity and bound bytes and time before trusting the hash."""
    try:
        deadline = monotonic() + safe_io.MAX_DISCOVERY_SECONDS
        descriptor = safe_io.open_read_descriptor(path)
        with os.fdopen(descriptor, "rb") as source:
            opened = safe_io.handle_snapshot(source.fileno())
            named = safe_io.checked_file_snapshot(path, boundary, relative)
            if isinstance(named, DiscoveryFailure):
                return named
            if not safe_io.same_identity(before, opened) or not safe_io.same_identity(opened, named):
                return DiscoveryFailure(DiscoveryFailureKind.IDENTITY_MISMATCH, relative, "path changed")
            if opened.byte_size > safe_io.MAX_DISCOVERY_BYTES:
                return DiscoveryFailure(DiscoveryFailureKind.RESOURCE_LIMIT, relative, "source exceeds discovery byte limit")
            return _hash_payload(source, relative, opened, declared, deadline)
    except OSError:
        return DiscoveryFailure(DiscoveryFailureKind.FILE_UNREADABLE, relative, "source cannot be read safely")

