create or replace function public.lock_era_item_parent() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_old uuid; v_new uuid; v_parent record;
begin
  if tg_op <> 'INSERT' then v_old := old.assessment_id; end if;
  if tg_op <> 'DELETE' then v_new := new.assessment_id; end if;
  for v_parent in
    select id,status from era_assessments where id in (v_old,v_new) order by id for update
  loop
    if current_setting('role',true) = 'authenticated' and v_parent.status not in ('draft','returned') then
      raise exception 'ERA items require a draft or returned assessment.' using errcode='55000';
    end if;
  end loop;
  return case when tg_op='DELETE' then old else new end;
end $$;
revoke all on function public.lock_era_item_parent() from public, anon, authenticated;
