create or replace function public.list_action_assignees(p_action uuid)
returns table(id uuid,name text,title text)
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v actions;
begin
  select * into v from actions where actions.id=p_action;
  if not found then
    raise exception 'Action % does not exist.',p_action using errcode='P0002';
  end if;
  if not has_site_role(v.site_id,array['plant_manager','dept_head']::app_role[]) then
    raise exception 'Action assignment permission is required.' using errcode='42501';
  end if;
  if v.status not in ('open','returned') then
    raise exception 'open 또는 returned 상태의 조치만 배정할 수 있습니다.';
  end if;
  return query select a.id,a.name,a.title from eligible_action_assignees(v.site_id) a order by a.name,a.id;
end $$;
